mapper.select:
SELECT kb_id kbId, COUNT(1) fileCount, SUM(file_size) fileTotalSize FROM knowledge_base_list WHERE status!=0 AND parse_type!=5 AND kb_id IN
#{kbId}
GROUP BY kb_id

SELECT count(1) FROM ( SELECT count(1) as t FROM knowledge_base_list WHERE ( STATUS != 0
and kb_id = #{kbId}
and kb_id in
#{kbId}
AND (id like concat('%',#{fuzzy},'%') or parent_file_name like concat('%',#{fuzzy},'%') or file_name like concat('%',#{fuzzy},'%') )
AND status = #{status}
AND faq_extract_status = #{faqExtractStatus}
AND parse_type IN (1,10)
AND parse_type IN (2,10)
AND parse_type IN (3)
) GROUP BY parent_file_name
HAVING count(1) > 1
HAVING count(1) == 1
) t

SELECT * FROM ( SELECT any_value ( id ) id, any_value ( kb_id ) kb_id, any_value ( group_id ) group_id, parent_file_name, 0 as is_folder, count(1) as count FROM knowledge_base_list WHERE ( STATUS != 0
and kb_id = #{kbId}
and kb_id in
#{kbId}
AND (id like concat('%',#{fuzzy},'%') or parent_file_name like concat('%',#{fuzzy},'%') or file_name like concat('%',#{fuzzy},'%') )
AND status = #{status}
AND faq_extract_status = #{faqExtractStatus}
AND parse_type IN (1,10)
AND parse_type IN (2,10)
AND parse_type = 3
) GROUP BY parent_file_name
HAVING count(1) > 1
HAVING count(1) = 1
) t ORDER BY t.count desc limit #{offSet},#{pageSize}

SELECT count(1) FROM ( SELECT
FROM folder_info t4 LEFT JOIN (SELECT id AS privilege_id,target_id FROM user_privilege WHERE is_del =1 AND user_id = #{params.userId} AND biz_type=6 AND permission=0 ) t3 ON t4.id = t3.target_id WHERE t4.status!=-1 AND t3.privilege_id IS NULL
AND kb_id=#{params.kbId} AND parent_id IS NULL
AND parent_id=#{params.folderId}
AND type IN
#{parsetype}
AND name LIKE concat('%',#{params.fuzzy},'%')
UNION ALL SELECT
FROM knowledge_base_list t1 LEFT JOIN (SELECT id,target_id FROM user_privilege WHERE is_del =1 AND user_id = #{params.userId} AND biz_type = 4 AND permission = 0 ) t2 ON t1.id = t2.target_id WHERE t1.status!=0 AND t2.id IS NULL
AND kb_id = #{params.kbId}
AND kb_id = #{params.kbId} AND folder_id IS null
AND folder_id=#{params.folderId}
AND file_name LIKE concat('%',#{params.fuzzy},'%')
AND parse_type IN
#{parsetype}
AND status in
#{status}
AND faq_extract_status = #{params.faqExtractStatus}
AND graph_parse_status IS NOT NULL AND graph_parse_status <> 0
) t

