mapper.sql:
(WITH RECURSIVE cte AS (SELECT c.id, c.parent_id FROM department_info AS c WHERE c.id = #{deptId}
UNION ALL
SELECT p.id, p.parent_id FROM department_info AS p INNER JOIN cte ON p.id = cte.parent_id) SELECT gp.target_id as target_id, gp.permission AS permission FROM cte LEFT JOIN user_group ug ON cte.id = ug.dept_id LEFT JOIN group_privilege gp ON ug.group_id = gp.group_id WHERE gp.biz_type = 4 AND permission > 0)

(WITH RECURSIVE cte AS (SELECT c.id, c.parent_id FROM department_info AS c WHERE c.id = #{deptId}
UNION ALL
SELECT p.id, p.parent_id FROM department_info AS p INNER JOIN cte ON p.id = cte.parent_id) SELECT gp.target_id as target_id, gp.permission AS permission FROM cte LEFT JOIN user_group ug ON cte.id = ug.dept_id LEFT JOIN group_privilege gp ON ug.group_id = gp.group_id WHERE gp.biz_type = 6 AND permission > 0)

(WITH RECURSIVE cte AS (SELECT c.id, c.parent_id FROM department_info AS c WHERE c.id = #{deptId}
UNION ALL
SELECT p.id, p.parent_id FROM department_info AS p INNER JOIN cte ON p.id = cte.parent_id) SELECT gp.target_id as target_id, gp.permission AS permission FROM cte LEFT JOIN user_group ug ON cte.id = ug.dept_id LEFT JOIN group_privilege gp ON ug.group_id = gp.group_id WHERE gp.biz_type = 4 AND permission = 0)

mapper.select:
SELECT any_value ( id ) id, any_value ( kb_id ) kb_id, any_value ( group_id ) group_id, parent_file_name FROM ( SELECT DISTINCT * FROM knowledge_base_list WHERE ( kb_id = #{kbId} and group_id=#{groupId} AND STATUS != 0 AND parse_type IN
#{parseType}
) ORDER BY gmt_create DESC ) t GROUP BY t.parent_file_name HAVING count( 1 ) > 1 LIMIT 1

WITH RECURSIVE folder_cte AS (SELECT id, parent_id FROM folder_info WHERE id = #{folderId}
UNION
SELECT f.id, f.parent_id FROM folder_info f INNER JOIN folder_cte cte ON f.parent_id = cte.id WHERE f.status = 1) SELECT target_id as id, GROUP_CONCAT(DISTINCT label) AS label, is_folder FROM (SELECT t1.id AS target_id, t2.label, 1 AS is_folder FROM folder_cte t1 LEFT JOIN biz_label t2 ON t1.id = t2.target_id WHERE t2.is_del = 1
UNION
SELECT t2.id AS target_id, t3.label, 0 AS is_folder FROM folder_cte t1 LEFT JOIN gienrag.knowledge_base_list t2 ON t1.id = t2.folder_id LEFT JOIN biz_label t3 ON t2.id = t3.target_id AND t3.is_del = 1 WHERE t2.status > 0) label_union GROUP BY target_id, is_folder;

